const PASSWORD='CASTLE';
const candidates=['CASTLE','BATTLE','CANDLE','RATTLE','CATTLE','PASTEL','MASTER','DANGER','CARPET','CASKET','FASTER','RASTER'];
const junk=['!','@','#','$','%','^','&','*','-','+','=','?','/','\\',';',':','.'];
let attempts=4,used=new Set(),duds=new Set(),bonusUsed=new Set(),revealed=new Set();
const dump=document.getElementById('memoryDump'),log=document.getElementById('hackLog'),blocks=document.getElementById('attemptBlocks');
const hints=[{text:'(^-)',type:'remove'},{text:'(.#)',type:'reveal'},{text:'(?;)',type:'trap'}];
function similarity(word){return [...word].filter((c,i)=>c===PASSWORD[i]).length}
function addLog(text,cls=''){const p=document.createElement('p');p.className=cls;p.textContent='> '+text;log.appendChild(p);log.scrollTop=log.scrollHeight}
function wordToken(word){return `<button class="token word${duds.has(word)?' used':''}" data-word="${word}">${word}</button>`}
function build(){dump.innerHTML='';const shuffled=[...candidates].sort(()=>Math.random()-.5);let wi=0,hi=0;for(let i=0;i<24;i++){const addr=(0xF400+i*12).toString(16).toUpperCase();let stream='';for(let j=0;j<12;){if((i+j)%7===0&&wi<shuffled.length){stream+=wordToken(shuffled[wi++]);j+=6}else if((i+j)%11===0&&hi<6){const hint=hints[hi++%hints.length];stream+=`<button class="token bracket" data-hint="${hint.type}" data-hint-id="${i}-${j}">${hint.text}</button>`;j+=4}else{stream+=`<span class="token">${junk[(i*5+j*3)%junk.length]}</span>`;j++}}dump.insertAdjacentHTML('beforeend',`<div class="dump-line"><span class="addr">0x${addr}</span><span>${stream}</span></div>`)}}
function updateAttempts(){blocks.textContent=[0,1,2,3].map(i=>i<attempts?'■':'□').join(' ')}
function lockIfEmpty(){if(attempts>0)return false;addLog('ТЕРМИНАЛ ЗАБЛОКИРОВАН','fail');document.querySelectorAll('.word,.bracket').forEach(x=>x.classList.add('used'));return true}
function choose(word,button){if(used.has(word)||attempts<=0)return;used.add(word);button.classList.add('used');addLog(word);if(word===PASSWORD){window.TerminalAudio?.success();addLog('ТОЧНОЕ СОВПАДЕНИЕ','success');addLog(`ПАРОЛЬ АРХИВА: ${PASSWORD}`,'success');addLog('ДОСТУП РАЗРЕШЁН','success');setTimeout(showVault,1700);return}window.TerminalAudio?.wrong();attempts--;addLog(`СОВПАДЕНИЕ: ${similarity(word)}/6`,'fail');updateAttempts();lockIfEmpty()}
function bonus(button,type,id){if(bonusUsed.has(id)||attempts<=0)return;bonusUsed.add(id);button.classList.add('used');if(type==='trap'){window.TerminalAudio?.wrong();attempts--;updateAttempts();addLog('ЛОЖНАЯ ПОДСКАЗКА: ПОПЫТКА ПОТЕРЯНА','fail');lockIfEmpty();return}window.TerminalAudio?.hint();if(type==='remove'){const possible=candidates.filter(x=>x!==PASSWORD&&!used.has(x)&&!duds.has(x));if(!possible.length){addLog('НЕТ ДОСТУПНЫХ ЛОЖНЫХ СЛОВ');return}const dud=possible[Math.floor(Math.random()*possible.length)];duds.add(dud);document.querySelectorAll(`[data-word="${dud}"]`).forEach(x=>x.classList.add('used'));addLog(`ЛОЖНОЕ СЛОВО УДАЛЕНО: ${dud}`,'success');return}const hidden=[0,1,2,3,4,5].filter(i=>!revealed.has(i));if(!hidden.length){addLog(`ПАРОЛЬ УЖЕ РАСКРЫТ: ${PASSWORD}`,'success');return}const position=hidden[Math.floor(Math.random()*hidden.length)];revealed.add(position);const mask=[...PASSWORD].map((c,i)=>revealed.has(i)?c:'#').join('');addLog(`ФРАГМЕНТ ПАРОЛЯ: ${mask}`,'success')}
function bind(){dump.querySelectorAll('.word').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.word,b)));dump.querySelectorAll('.bracket').forEach(b=>b.addEventListener('click',()=>bonus(b,b.dataset.hint,b.dataset.hintId)))}
function reset(){attempts=4;used.clear();duds.clear();bonusUsed.clear();revealed.clear();log.innerHTML='<p>&gt; НОВЫЙ ДАМП ЗАГРУЖЕН</p>';updateAttempts();build();bind()}
function showVault(){document.getElementById('hackView').classList.add('hidden');document.getElementById('vaultView').classList.remove('hidden');window.scrollTo(0,0)}
const accessDialog=document.getElementById('accessDialog'),choicePanel=document.getElementById('choicePanel'),passwordPanel=document.getElementById('passwordPanel'),passwordInput=document.getElementById('passwordInput'),passwordError=document.getElementById('passwordError');
function openGateway(){document.getElementById('hackView').classList.add('hidden');document.getElementById('vaultView').classList.add('hidden');choicePanel.classList.remove('hidden');passwordPanel.classList.add('hidden');passwordInput.value='';passwordError.textContent='';if(!accessDialog.open)accessDialog.showModal()}
document.getElementById('passwordChoice').addEventListener('click',()=>{choicePanel.classList.add('hidden');passwordPanel.classList.remove('hidden');passwordInput.focus()});
document.getElementById('backChoice').addEventListener('click',()=>{passwordPanel.classList.add('hidden');choicePanel.classList.remove('hidden');passwordError.textContent=''});
document.getElementById('hackChoice').addEventListener('click',()=>{accessDialog.close();document.getElementById('hackView').classList.remove('hidden');reset()});
passwordPanel.addEventListener('submit',e=>{e.preventDefault();if(passwordInput.value.trim().toLowerCase()==='baron'){accessDialog.close();showVault()}else{passwordError.textContent='ОТКАЗ: НЕВЕРНЫЙ ПАРОЛЬ';passwordInput.select()}});
accessDialog.addEventListener('cancel',e=>{e.preventDefault();location.href='fourth.html'});
document.getElementById('restartHack').addEventListener('click',reset);
window.addEventListener('pageshow',openGateway);
